// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Commands status and caps: halt flag, quiet hours, caps used and left
// Flo: open store > read stat windows + halt > compute effective caps > print text or JSON
// I/O: Ctx (caller) > stdout text or JSON; exit 0 ready, 4 halted
// ===================================================================
const std = @import("std"); const ctxz = @import("ct-ctrl-ctxz.zig"); const pace = @import("ru-huma-pace.zig");
pub const Out = struct { ok: bool, halted: ?[]const u8, quiet: bool, first_ms: i64, sent_hour: u32, sent_day: u32, newc_day: u32, cap_hour: u32, cap_day: u32, cap_newc: u32, warm: f64, left_hour: u32, left_day: u32 };
pub fn build(ctx: *ctxz.Ctx) !Out { var sto = try ctxz.openStor(ctx); defer sto.close(); const now = ctxz.nowMs(ctx); const sta = try sto.statGet(ctx.allo, now); const lim = pace.limsOf(ctx.cfg); const fact = pace.warmFact(sta.first_ms, now, lim.warm); const caph = pace.capEff(lim.hour, fact); const capd = pace.capEff(lim.dayz, fact); const halt = try sto.haltGet(ctx.allo); return .{ .ok = halt == null, .halted = halt, .quiet = pace.quietNow(now, lim.utcz, lim.qfrm, lim.qtoz), .first_ms = sta.first_ms, .sent_hour = sta.hour_cnt, .sent_day = sta.day_cnt, .newc_day = sta.newc_cnt, .cap_hour = caph, .cap_day = capd, .cap_newc = pace.capEff(lim.newc, fact), .warm = fact, .left_hour = caph -| sta.hour_cnt, .left_day = capd -| sta.day_cnt }; }
pub fn statRun(ctx: *ctxz.Ctx) !u8 { const out = try build(ctx); if (ctx.args.json) { try ctxz.emit(ctx, try std.json.Stringify.valueAlloc(ctx.allo, out, .{})); try ctxz.emit(ctx, "\n"); } else { try ctxz.emitf(ctx, "status: {s}\nhalt: {s}\nquiet hours now: {s}\nsent last hour: {d}/{d} · last day: {d}/{d} · new contacts: {d}/{d}\nwarm-up: {d:.0}%\n", .{ if (out.ok) "ready" else "HALTED", out.halted orelse "none", if (out.quiet) "yes" else "no", out.sent_hour, out.cap_hour, out.sent_day, out.cap_day, out.newc_day, out.cap_newc, out.warm * 100.0 }); } return if (out.ok) 0 else 4; }
pub fn capsRun(ctx: *ctxz.Ctx) !u8 { const out = try build(ctx); if (ctx.args.json) { try ctxz.emit(ctx, try std.json.Stringify.valueAlloc(ctx.allo, .{ .cap_hour = out.cap_hour, .cap_day = out.cap_day, .cap_newc = out.cap_newc, .left_hour = out.left_hour, .left_day = out.left_day, .warm = out.warm }, .{})); try ctxz.emit(ctx, "\n"); } else { try ctxz.emitf(ctx, "left this hour: {d} of {d}\nleft today: {d} of {d}\nnew contacts cap/day: {d}\nwarm-up: {d:.0}%\n", .{ out.left_hour, out.cap_hour, out.left_day, out.cap_day, out.cap_newc, out.warm * 100.0 }); } return 0; }
